import{_ as a,o as t,c as r,ao as n}from"./chunks/framework.DM2KPRmX.js";const u=JSON.parse('{"title":"Reactant integration","description":"","frontmatter":{},"headers":[],"relativePath":"reactant.md","filePath":"reactant.md","lastUpdated":null}'),i={name:"reactant.md"};function o(l,e,d,s,c,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="Reactant-integration" tabindex="-1">Reactant integration <a class="header-anchor" href="#Reactant-integration" aria-label="Permalink to &quot;Reactant integration {#Reactant-integration}&quot;">​</a></h1><p>Reactant is an optional compiler backend, not a dependency of native ReactiveKernels. The reviewed surface starts with scalar and batched distribution kernels, then the Eight Schools and MNIST PPL models, followed by compiled automatic differentiation.</p><p>The same <code>PreparedKernel</code> or <code>PreparedADKernel</code> boundary is traced; Reactant does not introduce a second model language. A Reactant path is supported only where the corresponding primal kernel compiles, and unsupported traced storage or control fails closed.</p><h2 id="Read-in-this-order" tabindex="-1">Read in this order <a class="header-anchor" href="#Read-in-this-order" aria-label="Permalink to &quot;Read in this order {#Read-in-this-order}&quot;">​</a></h2><ol start="2"><li><p><a href="./distributions-reactant">Distribution kernels through Reactant</a> — scalar, structured, and batched boundaries.</p></li><li><p><a href="./eight-schools-reactant">Eight Schools through Reactant</a> — reviewed PPL primal and value-and-gradient evidence.</p></li><li><p><a href="./mnist-reactant">MNIST through Reactant</a> — reviewed full-data model evidence.</p></li><li><p><a href="./reactant-ad">AD + Reactant</a> — the compiled prepared-AD API and its limits.</p></li></ol><p>Older throughput and experimental sampling receipts appear afterward. They are not promoted into the reviewed capability set, and sampling compiler/runtime code is not executed by the docs build.</p><h2 id="Current-boundary" tabindex="-1">Current boundary <a class="header-anchor" href="#Current-boundary" aria-label="Permalink to &quot;Current boundary {#Current-boundary}&quot;">​</a></h2><ul><li><p>Prepared scalar kernels and tensorized distribution plates are accepted.</p></li><li><p>A plate with at most 16 static lanes lowers as per-lane scalar recipes with a scalar reduction, so a small posterior fuses into one CPU kernel; larger plates keep the batched lowering. The automatic AD compile keeps bound arrays of at most 4096 elements embedded as compiler literals.</p></li><li><p>Whole-kernel <code>replica</code> preserves the scalar kernel as its source authority.</p></li><li><p>Compiled AD reuses the native single-active-port, scalar-WANT validation.</p></li><li><p>Unsupported scalar indexing, unbounded control, or structural state rejects; the docs do not paper over those errors with alternate implementations.</p></li><li><p>NUTS/WALNUTS pages are source- and receipt-only during documentation builds.</p></li></ul>',8)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
